import java.util.Scanner;

/**
 * MAIN: the only class that touches the Scanner. ONE Scanner, a local variable of main()
 * handed to the input methods - never a static field (the Guide forbids static variables in
 * Main). Validation only receives the String that was read. The prompts are left out so the
 * demo prints a single line.
 */
public final class Main {

    // Private constructor: Main only has static methods (checklist 3.4).
    private Main() {
    }

    // Starts the program: creates the one Scanner, then reads a name and an age with it.
    public static void main(String[] args) {
        // the real program writes new Scanner(System.in); fixed text keeps the demo repeatable
        Scanner sc = new Scanner("Tran Binh\n25\n");
        String name = "";
        int age = 0;

        // both reads go through the same Scanner, one whole line at a time
        name = inputName(sc);
        age = inputAge(sc);
        System.out.printf("%s is %d%n", name, age);
    }

    // Reads the name: the whole line, trimmed.
    private static String inputName(Scanner sc) {
        return sc.nextLine().trim();
    }

    // Reads lines until Validation accepts one as an age; the error is printed here, in Main.
    private static int inputAge(Scanner sc) {
        String line = "";

        // keep reading until the line is a valid age
        while (true) {
            line = sc.nextLine();

            // Validation throws with a text from Message; Main prints it and reads again
            try {
                return Validation.getAge(line);
            } catch (Exception e) {
                // print why the line was refused; the loop then reads the next line
                System.out.println(e.getMessage());
            }
        }
    }
}

/**
 * UTILS (utils/Validation.java in your project): receives the String that Main read. No
 * Scanner, no print - a wrong line throws, and Main prints the message.
 */
final class Validation {

    // Private constructor: every method is called through the class name.
    private Validation() {
    }

    // Converts the typed age; letters or an empty line throw Message.INVALID_AGE.
    public static int getAge(String input) throws Exception {
        int age = 0;

        // parse the trimmed line - never nextInt(), which chokes on letters
        try {
            age = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // not a whole number: the text comes from Message, not from a literal here
            throw new Exception(Message.INVALID_AGE);
        }

        return age;
    }
}

