/**
 * The String methods the LAB211 briefs need: trim, split, partial search, compare, match.
 */
public final class StringRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private StringRef() {
    }

    // Runs every String call once on one line of data and prints the result.
    public static void main(String[] args) {
        String rawLine = "  D001,Tran Binh,Cardiology  ";
        String line = rawLine.trim();
        String[] columnArray = line.split(",");
        String name = columnArray[1];
        String keyword = "BINH";

        // trim() removed the outer spaces; length() and isEmpty() measure what is left
        System.out.printf("[%s]%n", line);
        System.out.println(line.length());
        System.out.printf("%b %b%n", line.isEmpty(), "".isEmpty());

        // split(",") turned the data line into its columns
        System.out.printf("%d | %s%n", columnArray.length, name);

        // case-insensitive partial search - the "search by part of name" rule
        System.out.println(name.toLowerCase().contains(keyword.toLowerCase()));

        // cut, find and replace inside the name: "Tran", 5, "Tran_Binh"
        System.out.println(name.substring(0, 4));
        System.out.println(name.indexOf("Binh"));
        System.out.println(name.replace(" ", "_"));

        // join puts the columns back together with a separator
        System.out.println(String.join(" | ", columnArray));

        // equals is case-sensitive, equalsIgnoreCase is not; matches tests the WHOLE text
        System.out.printf("%b %b%n", "abc".equals("ABC"), "abc".equalsIgnoreCase("ABC"));
        System.out.println("D001".matches("D\\d{3}"));
        System.out.println("D1".matches("D\\d{3}"));
    }
}

