/**
 * Integer.parseInt and Double.parseDouble, and the guard around them. convertToInt has the
 * shape of a Validation method: it receives the String that Main read and never prints.
 */
public final class ParseRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private ParseRef() {
    }

    // Returns the int in the text, or null when it is not an int - the caller decides what
    // to say.
    public static Integer convertToInt(String input) {
        // parseInt throws NumberFormatException on letters, "4.2" or an empty text
        try {
            return Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // not a whole number: no message here - Main prints one
            return null;
        }
    }

    // Converts a few texts and prints what comes back.
