        System.out.println(convertToInt("4.2"));
        System.out.println(convertToInt("abc"));
        System.out.println(convertToInt(""));

        // a decimal number, a number written in base 16, an int shown in base 2
        System.out.println(Double.parseDouble("1234.5"));
        System.out.println(Integer.parseInt("FF", 16));
        System.out.println(Integer.toBinaryString(10));
