/**
 * The List operations a CRUD program needs: add, insert, get, contains, indexOf, set,
 * remove, and deleting safely while looping.
 */
public final class ListRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private ListRef() {
    }

    // Runs every List operation once and prints the list after it.
    public static void main(String[] args) {
        List<String> idList = new ArrayList<>();
        List<Integer> numberList = new ArrayList<>(Arrays.asList(1, 2, 2, 3));
        List<String> copyList = null;

        // add at the end twice, then insert at position 1
        idList.add("D001");
        idList.add("D002");
        idList.add(1, "D003");
        System.out.printf("%s size=%d%n", idList, idList.size());
        System.out.printf("%s %b %d%n", idList.get(0), idList.contains("D002"),
                idList.indexOf("D002"));

        // update position 0, then delete by value
        idList.set(0, "D009");
        idList.remove("D003");
        System.out.println(idList);

        // iterate safely while deleting: go backwards, so no position is skipped
        for (int i = numberList.size() - 1; i >= 0; i--) {
            int value = numberList.get(i);

            // remove(int) deletes by position, which is what this loop wants
            if (value == 2) {
                numberList.remove(i);
            }
        }

        System.out.println(numberList);

        // defensive copy: reversing the copy leaves idList as it was
        copyList = new ArrayList<>(idList);
        Collections.reverse(copyList);
        System.out.println(copyList);
    }
}

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Map: find by id in one step. containsKey is the "check duplicate Id" rule of the briefs.
 */
public final class MapRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private MapRef() {
    }

    // Runs every Map operation once and prints the result.
    public static void main(String[] args) {
        Map<String, Double> salaryMap = new LinkedHashMap<>();

        // LinkedHashMap keeps the order in which the keys were put
        salaryMap.put("E001", 1200.0);
        salaryMap.put("E002", 900.0);

        // containsKey is the duplicate check; get of a missing key is null, NOT an error
        System.out.println(salaryMap.containsKey("E001"));
        System.out.println(salaryMap.get("E999"));
        System.out.println(salaryMap.getOrDefault("E999", 0.0));

        // put with a key that is already there replaces the value: the size stays 2
        salaryMap.put("E001", 1500.0);
        System.out.println(salaryMap.size());

        // walk every entry, in insertion order
        for (Map.Entry<String, Double> entry : salaryMap.entrySet()) {
            System.out.printf("%s -> %.1f%n", entry.getKey(), entry.getValue());
        }

        // delete by key, then list the keys that are left
        salaryMap.remove("E002");
        System.out.println(salaryMap.keySet());
    }
}

