/**
 * Library sorting: Arrays.sort for primitives, Collections.sort and List.sort with a
 * Comparator for objects. In LAB211 the sort lives in the Service, never in the Controller.
 */
public final class SortRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private SortRef() {
    }

    // Sorts numbers, names and doctors, printing each result.
    public static void main(String[] args) {
        int[] numberArray = {5, 1, 12, -5};
        List<String> nameList = new ArrayList<>(Arrays.asList("Le", "An", "Binh"));
        List<Doctor> doctorList = new ArrayList<>(Arrays.asList(
                new Doctor("D2", "Hoa", 900), new Doctor("D1", "An", 1500),
                new Doctor("D3", "Binh", 900)));

        // primitives: ascending only
        Arrays.sort(numberArray);
        System.out.println(Arrays.toString(numberArray));

        // natural order, then the reverse of it
        Collections.sort(nameList);
        System.out.println(nameList);
        nameList.sort(Comparator.reverseOrder());
        System.out.println(nameList);

        // salary ascending; equal salaries keep their order because the sort is stable
        doctorList.sort(Comparator.comparingDouble(Doctor::getSalary));
        System.out.println(getNameList(doctorList));

        // salary descending, then name ascending when the salaries are equal
        doctorList.sort(Comparator.comparingDouble(Doctor::getSalary).reversed()
                .thenComparing(Doctor::getName));
        System.out.println(getNameList(doctorList));
    }

    // Returns the names of the doctors, in the current order of the list.
    private static List<String> getNameList(List<Doctor> doctorList) {
        return doctorList.stream().map(Doctor::getName).collect(Collectors.toList());
    }
}

