import java.util.Arrays;

/**
 * Math in the two shapes this course needs: random test data and geometry.
 */
public final class MathRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private MathRef() {
    }

    // Fills an array with random numbers, then prints the geometry formulas.
    public static void main(String[] args) {
        int[] valueArray = new int[8];
        boolean allInRange = false;
        double radius = 2.0;
        double side = 3.0;

        // 1. random test data - "generate random integer in number range": 0..99
        for (int i = 0; i < valueArray.length; i++) {
            valueArray[i] = (int) (Math.random() * 100);
        }

        // every value must be in [0, 100): one pair of parentheses per comparison
        allInRange = Arrays.stream(valueArray).allMatch(value -> (value >= 0) && (value < 100));
        System.out.printf("%d values, all in range: %b%n", valueArray.length, allInRange);

        // 2. geometry
        System.out.printf("circle area      %.2f%n", Math.PI * radius * radius);
        System.out.printf("circle perimeter %.2f%n", 2 * Math.PI * radius);
        System.out.printf("sphere volume    %.2f%n", (4.0 / 3.0) * Math.PI * Math.pow(radius, 3));
        System.out.printf("cube surface     %.2f%n", 6 * side * side);

        // square root, absolute value, rounding to the nearest whole number
        System.out.printf("%s %d %d%n", Math.sqrt(16), Math.abs(-7), Math.round(2.567));
    }
}

import java.time.LocalDate;
import java.time.Period;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;

/**
 * LocalDate and the two resolver modes: SMART (the default) clamps 31/02 to 28/02, STRICT
 * refuses it. parseDate is the method to copy into utils/Validation.
 */
public final class DateRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private DateRef() {
    }

    // Returns the date, or null when the text is not a real date - 31/02 included.
    public static LocalDate parseDate(String input) {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern(Constants.DATE_PATTERN)
                .withResolverStyle(ResolverStyle.STRICT);

        // STRICT refuses an impossible day instead of moving it to the end of the month
        try {
            return LocalDate.parse(input.trim(), formatter);
        } catch (DateTimeParseException e) {
            // not a real date, or not in the pattern: no message here - Main prints one
            return null;
        }
    }

    // Parses a few dates both ways and prints what comes back.
    public static void main(String[] args) {
        DateTimeFormatter looseFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
        DateTimeFormatter printFormatter = DateTimeFormatter.ofPattern(Constants.DATE_PATTERN);
        LocalDate birthDate = parseDate("03/11/2003");

        // a real date: toString(), the pattern of the briefs, and one field
        System.out.printf("%s | %s | year %d%n", birthDate, birthDate.format(printFormatter),
                birthDate.getYear());

        // SMART (the default) turns 31/02 into 28/02 without a word - CLAMPED!
        System.out.println(LocalDate.parse("31/02/2003", looseFormatter));

        // STRICT refuses 31/02, accepts a real leap day, refuses the wrong pattern
        System.out.println(parseDate("31/02/2003"));
        System.out.println(parseDate("29/02/2024"));
        System.out.println(parseDate("2003-11-03"));

        // compare two dates, then count the whole years between them
        System.out.println(birthDate.isBefore(LocalDate.of(2010, 1, 1)));
        System.out.printf("%d years old%n",
                Period.between(birthDate, LocalDate.of(2026, 7, 21)).getYears());
    }
}

