/**
 * UTILS (utils/FileUtils.java in your project): reads and writes a text file line by line.
 * Static methods only; it does not know what a line means and it never prints.
 */
final class FileUtils {

    // Private constructor: every method is called through the class name.
    private FileUtils() {
    }

    // Reads every non-blank line; a file that does not exist yet gives an empty list.
    public static List<String> readLines(String path) throws IOException {
        List<String> lineList = new ArrayList<>();
        File file = new File(path);
        String line = "";

        // first run: no file means no data yet, not an error
        if (!file.exists()) {
            return lineList;
        }

        // try-with-resources closes the file even when reading fails
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            line = reader.readLine();

            // readLine() returns null at the end of the file
            while (line != null) {
                // skip blank lines, such as an empty last line
                if (!line.trim().isEmpty()) {
                    lineList.add(line);
                }

                line = reader.readLine();
            }
        }

        return lineList;
    }

    // Replaces the whole file with the given lines, one element per line.
    public static void writeLines(String path, List<String> lineList) throws IOException {
        // try-with-resources flushes and closes the file even when writing fails
        try (PrintWriter writer = new PrintWriter(new FileWriter(path))) {
            // one element of the list = one line of the file
            for (String line : lineList) {
                writer.println(line);
            }
        }
    }
}

