/**
 * toString, equals and hashCode: what printing a list, contains() and a HashSet rely on.
 */
public final class ObjectRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private ObjectRef() {
    }

    // Shows each overridden method at work on a list and a set of fruits.
    public static void main(String[] args) {
        List<Fruit> fruitList = new ArrayList<>(Arrays.asList(new Fruit("F1", "Apple"),
                new Fruit("F2", "Mango")));
        Set<Fruit> fruitSet = new HashSet<>(fruitList);

        // toString: printing the list prints every fruit
        System.out.println(fruitList);

        // equals: contains() finds F1 although the name is different
        System.out.println(fruitList.contains(new Fruit("F1", "any")));

        // hashCode: the set built from the list holds both fruits
        System.out.println(fruitSet.size());

        // same id -> not added: the set still holds 2
        fruitSet.add(new Fruit("F1", "Apple again"));
        System.out.println(fruitSet.size());
    }
}

/**
 * MODEL: a fruit whose identity is its id - fields, constructor and Object methods only.
 */
class Fruit {

    // Identity of the fruit, for example F1.
    private final String id;

    // Display name; two fruits with the same id are equal whatever their names.
    private final String name;

    // Creates a fruit.
    Fruit(String id, String name) {
        this.id = id;
        this.name = name;
    }

    // Returns "id:name" - what printing a list shows.
    @Override
    public String toString() {
        return String.format(Constants.FRUIT_FORMAT, id, name);
    }

    // Two fruits are equal when their ids are equal: the id is the identity.
    @Override
    public boolean equals(Object object) {
        Fruit other = null;

        // the very same object: equal without looking further
        if (this == object) {
            return true;
        }

        // null or not a Fruit: never equal
        if (!(object instanceof Fruit)) {
            return false;
        }

        other = (Fruit) object;
        return id.equals(other.id);
    }

    // Same id, same hash: must agree with equals, or a HashSet looks in the wrong bucket.
    @Override
    public int hashCode() {
        return id.hashCode();
    }
}

