/**
 * StringBuilder, and MD5 the way LAB211 uses it: Main hashes the password with MD5Utils
 * before putting it into the request DTO; the repository only stores and compares hashes.
 */
public final class RareRef {

    // Private constructor: this class only has static methods (checklist 3.4).
    private RareRef() {
    }

    // Builds "3-2-1" in a loop with StringBuilder, then hashes "123456".
    public static void main(String[] args) throws NoSuchAlgorithmException {
        StringBuilder numberBuilder = new StringBuilder();
        String forward = "";
        String backward = "";

        // append in a loop - never String += inside a loop
        for (int i = 3; i >= 1; i--) {
            numberBuilder.append(i).append((i > 1) ? "-" : "");
        }

        // take the text BEFORE reverse(): reverse() changes the builder itself
        forward = numberBuilder.toString();
        backward = numberBuilder.reverse().toString();
        System.out.printf("%s | %s%n", forward, backward);

        // 32 hex characters, and the same input always gives the same digest
        System.out.println(MD5Utils.hashMd5("123456"));
        System.out.println(MD5Utils.hashMd5("123456").length());
        System.out.println(MD5Utils.hashMd5("123456").equals(MD5Utils.hashMd5("123456")));
    }
}

/**
 * UTILS (utils/MD5Utils.java in your project): the MD5 hex digest - what the login brief
 * means by "MD5 encryption".
 */
final class MD5Utils {

    // Private constructor: every method is called through the class name.
    private MD5Utils() {
    }

    // Returns the MD5 digest of the text as 32 lower-case hex characters.
    public static String hashMd5(String text) throws NoSuchAlgorithmException {
        MessageDigest messageDigest = MessageDigest.getInstance(Constants.MD5_ALGORITHM);
        byte[] digestArray = messageDigest.digest(text.getBytes(StandardCharsets.UTF_8));
        StringBuilder hexBuilder = new StringBuilder();

        // two hex digits per byte; %02x keeps the leading zero
        for (byte oneByte : digestArray) {
            hexBuilder.append(String.format(Constants.HEX_FORMAT, oneByte));
        }

        return hexBuilder.toString();
    }
}

